(()=>{
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const fine=matchMedia('(hover: hover) and (pointer: fine)');
 let paused=false;try{paused=localStorage.getItem('cac-motion-paused')==='true'}catch{}
 const running=new Set();
 const toggle=document.createElement('button');toggle.type='button';toggle.className='motion-toggle';document.body.append(toggle);
 const off=()=>paused||reduced.matches;
 function sync(){document.documentElement.classList.toggle('motion-paused',off());toggle.textContent=reduced.matches?'Reduced motion':paused?'Enable animations':'Pause animations';toggle.setAttribute('aria-pressed',String(off()));toggle.disabled=reduced.matches;if(off()){running.forEach(a=>a.cancel());running.clear();document.querySelectorAll('.depth-surface').forEach(reset)}}
 toggle.addEventListener('click',()=>{paused=!paused;try{localStorage.setItem('cac-motion-paused',String(paused))}catch{}sync()});reduced.addEventListener('change',sync);sync();
 function reset(el){el.style.removeProperty('--tilt-x');el.style.removeProperty('--tilt-y');el.style.removeProperty('--shine-x');el.style.removeProperty('--shine-y')}
 document.querySelectorAll('.district-card,.church-brand-art,.flyer,.welcome-copy,.address').forEach(el=>{el.classList.add('depth-surface');let frame=0;el.addEventListener('pointermove',e=>{if(off()||!fine.matches||e.pointerType==='touch')return;if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{frame=0;const r=el.getBoundingClientRect(),x=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width)),y=Math.max(0,Math.min(1,(e.clientY-r.top)/r.height));el.style.setProperty('--tilt-x',`${(0.5-y)*5}deg`);el.style.setProperty('--tilt-y',`${(x-0.5)*5}deg`);el.style.setProperty('--shine-x',`${x*100}%`);el.style.setProperty('--shine-y',`${y*100}%`);});});el.addEventListener('pointerleave',()=>{cancelAnimationFrame(frame);frame=0;reset(el)});});
 if('IntersectionObserver'in window&&Element.prototype.animate){const observer=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(!entry.isIntersecting)return;observer.unobserve(entry.target);if(off())return;const el=entry.target;const a=el.animate([{opacity:.15,translate:'0 28px',filter:'blur(3px)'},{opacity:1,translate:'0 0',filter:'blur(0)'}],{duration:800,delay:el.matches('.district-card')?[...el.parentElement.children].indexOf(el)*90:0,easing:'cubic-bezier(.16,1,.3,1)'});running.add(a);a.onfinish=()=>running.delete(a)});},{threshold:.1});document.querySelectorAll('.location-strip,.welcome>div,.scripture,.leadership>div:not(.district-leadership),.church-brand-art,.district-card,.district-leadership>h3,.update-grid>*,.visit>div,.footer').forEach(el=>observer.observe(el))}
 document.addEventListener('visibilitychange',()=>{running.forEach(a=>{if(document.hidden)a.pause();else if(!off())a.play()})});
 document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.querySelector('nav')?.classList.remove('open');document.querySelector('.menu')?.setAttribute('aria-expanded','false')}});
})();
